  q(IMM,'An antibody titer of 1:512 means what?','Antibody was still detected after diluting the serum 512 times',['There are 512 antibodies in total','The patient has 512 infections','The test failed 512 times'],'A','Higher titers mean more antibody is present, which may show recent infection or immunity.',BR),
  q(IMM,'Which antibody class is the main one found in tears, saliva and breast milk?','IgA',['IgM','IgE','IgD'],'B','Secretory IgA protects mucous membranes, and breast milk passes it to nursing infants.',ST)
